{"path": "/tmp/sv-2c67b6573431499cba4c54154a9b13b4/Components/Board/TaskCard.razor", "file_text": "<div class="task-card priority-@Task.Priority.ToLowerInvariant()">
    <h4 class="task-title">@Task.Title</h4>
    <p class="task-assignee">@Task.Assignee</p>
    <div class="task-meta">
        <span class="priority-badge @GetPriorityClass()">@Task.Priority</span>
        <span class="task-due">@Task.DueDate.ToString("MMM dd")</span>
    </div>
    <div class="task-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move" @onclick="() => OnMoveLeft.InvokeAsync(Task)" disabled="@IsMoving">← Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move" @onclick="() => OnMoveRight.InvokeAsync(Task)" disabled="@IsMoving">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public bool IsMoving { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRight { get; set; }

    private string GetPriorityClass() => Task.Priority switch
    {
        "High" => "badge-high",
        "Medium" => "badge-medium",
        "Low" => "badge-low",
        _ => ""
    };
}
"}

{"path": "/tmp/sv-2c67b6573431499cba4c54154a9b13b4/Components/Board/AddTaskForm.razor", "file_text": "<div class="add-task-form">
    <div class="form-field">
        <label>Title</label>
        <input type="text" @bind="title" placeholder="Task title" />
    </div>
    <div class="form-field">
        <label>Assignee</label>
        <input type="text" @bind="assignee" placeholder="Assignee name" />
    </div>
    <div class="form-field">
        <label>Priority</label>
        <select @bind="priority">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
    </div>
    <div class="form-field">
        <label>Due Date</label>
        <input type="date" @bind="dueDate" />
    </div>
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save")
        </button>
        <button class="btn-cancel" @onclick="HandleCancel" disabled="@isSaving">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string DefaultStatus { get; set; } = "";
    [Parameter] public EventCallback<TaskItem> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string title = "";
    private string assignee = "";
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);
    private bool isSaving;

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(title)) return;

        isSaving = true;
        try
        {
            var newTask = new TaskItem(0, title, assignee, priority, dueDate, DefaultStatus);
            await OnSave.InvokeAsync(newTask);
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task HandleCancel()
    {
        await OnCancel.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-2c67b6573431499cba4c54154a9b13b4/Components/Board/BoardSearchBar.razor", "file_text": "<div class="board-search">
    <input type="text"
           placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = "";
    [Parameter] public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? "");
    }
}
"}

{"path": "/tmp/sv-2c67b6573431499cba4c54154a9b13b4/Components/Board/KanbanColumn.razor", "file_text": "<div class="kanban-column">
    <div class="column-header">
        <h3>@Title <span class="column-count">(@Tasks.Count)</span></h3>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      IsMoving="movingTaskId == task.Id"
                      OnMoveLeft="HandleMoveLeft"
                      OnMoveRight="HandleMoveRight" />
        }
    </div>

    @if (showAddForm)
    {
        <AddTaskForm DefaultStatus="Status"
                     OnSave="HandleTaskSaved"
                     OnCancel="() => showAddForm = false" />
    }
    else
    {
        <button class="btn-add-task" @onclick="() => showAddForm = true">+ Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = "";
    [Parameter, EditorRequired] public string Status { get; set; } = "";
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = [];
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }

    private bool showAddForm;
    private int? movingTaskId;

    private async Task HandleMoveLeft(TaskItem task)
    {
        movingTaskId = task.Id;
        try { await OnMoveLeft.InvokeAsync(task); }
        finally { movingTaskId = null; }
    }

    private async Task HandleMoveRight(TaskItem task)
    {
        movingTaskId = task.Id;
        try { await OnMoveRight.InvokeAsync(task); }
        finally { movingTaskId = null; }
    }

    private async Task HandleTaskSaved(TaskItem task)
    {
        await OnTaskCreated.InvokeAsync(task);
        showAddForm = false;
    }
}
"}

